return [
    'id' => 'ms-copilot', 'family' => 'assistants', 'after' => null, 'categories' => ['ai', 'productivity'],
    'title' => L('Microsoft Copilot', 'Microsoft Copilot'), 'short' => L('MS Copilot', 'MS Copilot'), 'level' => L('Base', 'Basics'),
    'desc' => L('L’AI dentro Word, Excel, PowerPoint, Outlook e Teams: scrivere prompt efficaci, analizzare dati, riassumere riunioni, proteggere i dati aziendali e usare agenti come Researcher e Analyst.', 'AI inside Word, Excel, PowerPoint, Outlook and Teams: writing effective prompts, analysing data, summarising meetings, protecting company data and using agents such as Researcher and Analyst.'),
    'lessons' => [
        lesson('intro', L('Copilot e Microsoft 365', 'Copilot and Microsoft 365'), [
            P('**Microsoft Copilot** è l’assistente AI di Microsoft: c’è l’app Copilot per tutti (web, Windows, telefono) e **Microsoft 365 Copilot** per le aziende, che lavora dentro Word, Excel, PowerPoint, Outlook e Teams e può usare i documenti, le email e le riunioni a cui **tu hai già accesso**.', '**Microsoft Copilot** is Microsoft’s AI assistant: there is the Copilot app for everyone (web, Windows, phone) and **Microsoft 365 Copilot** for companies, which works inside Word, Excel, PowerPoint, Outlook and Teams and can use the documents, emails and meetings **you already have access to**.'),
            P('Microsoft suggerisce di costruire le richieste con quattro elementi: **obiettivo** (cosa vuoi), **contesto** (perché, per chi), **fonti** (quali file o email usare) e **aspettative** (formato, tono, lunghezza).', 'Microsoft suggests building requests with four elements: **goal** (what you want), **context** (why, for whom), **sources** (which files or emails to use) and **expectations** (format, tone, length).'),
            C('Obiettivo: prepara una mail di aggiornamento sul progetto Alfa.
Contesto: la leggerà il direttore, che non segue i dettagli tecnici.
Fonti: usa /Verbale riunione 3 novembre e la mail di Luca sul budget.
Aspettative: 5 punti, tono professionale, massimo 150 parole.', 'text'),
        ], [
            Q('i1', L('A quali dati accede Microsoft 365 Copilot?', 'Which data does Microsoft 365 Copilot access?'), [L('A quelli a cui l’utente ha già accesso', 'Those the user already has access to'), L('A tutti i file dell’azienda', 'All company files'), L('A nessun dato', 'No data'), L('Solo a internet', 'Only the internet')], 0, L('Rispetta i permessi esistenti.', 'It respects existing permissions.')),
            Q('i2', L('Quali sono i quattro elementi di un buon prompt secondo Microsoft?', 'What are the four elements of a good prompt per Microsoft?'), [L('Obiettivo, contesto, fonti, aspettative', 'Goal, context, sources, expectations'), L('Titolo, data, firma, allegato', 'Title, date, signature, attachment'), L('Domanda, risposta, voto, commento', 'Question, answer, score, comment'), L('Nessuno', 'None')], 0, L('Una struttura semplice.', 'A simple structure.')),
            Q('i3', L('Dove funziona Microsoft 365 Copilot?', 'Where does Microsoft 365 Copilot work?'), [L('Dentro Word, Excel, PowerPoint, Outlook e Teams', 'Inside Word, Excel, PowerPoint, Outlook and Teams'), L('Solo nel browser', 'Only in the browser'), L('Solo su Mac', 'Only on Mac'), L('Solo nei giochi', 'Only in games')], 0, L('Nelle app di ogni giorno.', 'In everyday apps.')),
        ], task('text', L('Scrivi un prompt per Copilot con le quattro righe `Obiettivo:`, `Contesto:`, `Fonti:` e `Aspettative:` per preparare l’ordine del giorno di una riunione.', 'Write a Copilot prompt with the four lines `Goal:`, `Context:`, `Sources:` and `Expectations:` to prepare a meeting agenda.'), "Obiettivo: \nContesto: \nFonti: \nAspettative: ", [re('^(Obiettivo|Goal):\s*\S.{5,}', L('Obiettivo', 'Goal')), re('^(Contesto|Context):\s*\S.{5,}', L('Contesto', 'Context')), re('^(Fonti|Sources):\s*\S.{3,}', L('Fonti', 'Sources')), re('^(Aspettative|Expectations):\s*\S.{5,}', L('Aspettative', 'Expectations'))], '', "Obiettivo: prepara l’ordine del giorno della riunione di lunedì.\nContesto: riunione di 30 minuti con il team vendite.\nFonti: usa le mail della settimana con oggetto “Offerte”.\nAspettative: elenco di 4 punti con il tempo per ciascuno."), [
            dMatch(pMatch(), [[L('Obiettivo', 'Goal'), L('Cosa vuoi ottenere', 'What you want')], [L('Contesto', 'Context'), L('Perché e per chi', 'Why and for whom')], [L('Fonti', 'Sources'), L('File ed email da usare', 'Files and emails to use')], [L('Aspettative', 'Expectations'), L('Formato, tono, lunghezza', 'Format, tone, length')]], L('Il prompt in quattro parti.', 'The four-part prompt.')),
            dFlash(pFlash(), [[L('Copilot rispetta i permessi sui file', 'Copilot respects file permissions'), true], [L('Copilot vede i file dei colleghi anche senza permesso', 'Copilot sees colleagues’ files without permission'), false], [L('Esiste un’app Copilot anche per i privati', 'There is a Copilot app for individuals too'), true], [L('Indicare le fonti peggiora le risposte', 'Naming sources worsens answers'), false]], L('Copilot nell’ufficio.', 'Copilot in the office.')),
        ]),
        lesson('word', L('Word e Outlook', 'Word and Outlook'), [
            P('In **Word** Copilot scrive bozze partendo da una richiesta o da altri documenti, riscrive paragrafi con un tono diverso, riassume documenti lunghi e risponde a domande sul testo. In **Outlook** riassume lunghe catene di email, propone risposte e aiuta a preparare messaggi.', 'In **Word** Copilot drafts from a request or from other documents, rewrites paragraphs in a different tone, summarises long documents and answers questions about the text. In **Outlook** it summarises long email threads, suggests replies and helps prepare messages.'),
            C('Word:    "Crea una bozza di offerta usando /Listino 2026 e /Offerta Rossi,
          con un’introduzione, 3 sezioni e un riepilogo dei prezzi."
Word:    "Riassumi questo documento in 5 punti per chi ha 2 minuti."
Outlook: "Riassumi questa conversazione e dimmi quali decisioni sono state prese."
Outlook: "Rispondi accettando la riunione ma proponendo le 15 invece delle 10."', 'text'),
            P('Rileggi sempre prima di inviare: nomi, cifre e date sono i punti dove gli errori fanno più danni. Un buon metodo: chiedi la bozza, poi correggi con indicazioni precise (“accorcia il secondo paragrafo”, “tono più cordiale”).', 'Always reread before sending: names, figures and dates are where mistakes do the most damage. A good method: ask for the draft, then refine with precise instructions (“shorten the second paragraph”, “warmer tone”).'),
        ], [
            Q('w1', L('Che cosa può fare Copilot in Outlook?', 'What can Copilot do in Outlook?'), [L('Riassumere catene di email e proporre risposte', 'Summarise threads and suggest replies'), L('Cancellare la casella', 'Delete the mailbox'), L('Inviare email da solo senza controllo', 'Send email by itself unchecked'), L('Cambiare password', 'Change passwords')], 0, L('Tu decidi cosa inviare.', 'You decide what to send.')),
            Q('w2', L('Che cosa controllare per primo in una bozza?', 'What should you check first in a draft?'), [L('Nomi, cifre e date', 'Names, figures and dates'), L('Il colore del testo', 'Text colour'), L('Il font', 'The font'), L('Niente', 'Nothing')], 0, L('Lì gli errori costano di più.', 'Errors cost most there.')),
            Q('w3', L('Come si migliora una bozza di Copilot?', 'How do you improve a Copilot draft?'), [L('Con indicazioni precise su cosa cambiare', 'With precise instructions on what to change'), L('Ricominciando sempre da zero', 'Always starting over'), L('Accettandola così', 'Accepting it as is'), L('Non si può', 'You cannot')], 0, L('Un passo alla volta.', 'One step at a time.')),
        ], task('text', L('Scrivi una richiesta per Copilot in Outlook che riassuma una conversazione in **3 punti** ed elenchi le **decisioni** e le **scadenze**.', 'Write a request for Copilot in Outlook that summarises a thread in **3 points** and lists the **decisions** and **deadlines**.'), '', [re('riassum|summar', L('Chiedi un riassunto', 'You ask for a summary')), re('3\s*(punti|points)|tre punti|three points', L('Tre punti', 'Three points')), re('decision', L('Le decisioni', 'The decisions')), re('scadenz|deadline', L('Le scadenze', 'The deadlines'))], '', 'Riassumi questa conversazione in 3 punti, poi elenca le decisioni prese e le scadenze con i responsabili.'), [
            dMatch(pMatch(), [[L('Bozza in Word', 'Draft in Word'), L('Da richiesta o documenti', 'From request or documents')], [L('Riassunto', 'Summary'), L('Documenti o email lunghe', 'Long documents or emails')], [L('Riscrittura', 'Rewrite'), L('Tono diverso', 'Different tone')], [L('Risposta in Outlook', 'Reply in Outlook'), L('Proposta da rileggere', 'Proposal to reread')]], L('Scrivere con Copilot.', 'Writing with Copilot.')),
            dFlash(pFlash(), [[L('Copilot in Word può partire da altri documenti', 'Copilot in Word can start from other documents'), true], [L('Le bozze si inviano senza rileggerle', 'Drafts are sent without rereading'), false], [L('Si può chiedere un tono più cordiale', 'You can ask for a warmer tone'), true], [L('Copilot non sa riassumere le email', 'Copilot cannot summarise emails'), false]], L('Bozze veloci, controllo umano.', 'Fast drafts, human check.')),
        ]),
        lesson('excel', L('Excel e PowerPoint', 'Excel and PowerPoint'), [
            P('In **Excel** Copilot crea formule, evidenzia dati, costruisce tabelle pivot e grafici e trova tendenze: funziona meglio con i dati in una **tabella** formattata (Inserisci → Tabella) con intestazioni chiare. In **PowerPoint** crea presentazioni da un documento o da una richiesta e riassume slide esistenti.', 'In **Excel** Copilot creates formulas, highlights data, builds pivot tables and charts and spots trends: it works best with data in a formatted **table** (Insert → Table) with clear headers. In **PowerPoint** it creates presentations from a document or a request and summarises existing slides.'),
            C('Excel:      "Aggiungi una colonna con il margine percentuale tra Prezzo e Costo."
Excel:      "Mostrami le vendite totali per regione in un grafico a barre."
Excel:      "Evidenzia in rosso i clienti senza ordini negli ultimi 90 giorni."
PowerPoint: "Crea 8 slide da /Relazione annuale.docx per il consiglio di amministrazione."', 'text'),
            P('Controlla sempre le formule create (clicca sulla cella e leggila) e verifica qualche risultato a mano: un riferimento sbagliato rovina tutti i numeri a valle.', 'Always check the formulas created (click the cell and read it) and verify a few results by hand: one wrong reference spoils every number downstream.'),
        ], [
            Q('x1', L('Come rendi i dati più facili da usare per Copilot in Excel?', 'How do you make data easier for Copilot in Excel?'), [L('In una tabella formattata con intestazioni chiare', 'In a formatted table with clear headers'), L('Celle unite ovunque', 'Merged cells everywhere'), L('Senza intestazioni', 'Without headers'), L('In un’immagine', 'In an image')], 0, L('Inserisci → Tabella.', 'Insert → Table.')),
            Q('x2', L('Che cosa controllare dopo che Copilot crea una formula?', 'What should you check after Copilot creates a formula?'), [L('La formula e qualche risultato a mano', 'The formula and a few results by hand'), L('Il colore delle celle', 'Cell colours'), L('Niente', 'Nothing'), L('Il nome del file', 'The file name')], 0, L('Un riferimento sbagliato rovina tutto.', 'A wrong reference spoils everything.')),
            Q('x3', L('Da che cosa può partire Copilot in PowerPoint?', 'What can Copilot in PowerPoint start from?'), [L('Da un documento o da una richiesta', 'From a document or a request'), L('Solo da un video', 'Only from a video'), L('Da nulla', 'From nothing'), L('Solo da Excel', 'Only from Excel')], 0, L('Poi si rifinisce.', 'Then you refine.')),
        ], task('text', L('Scrivi una richiesta per Copilot in Excel che aggiunga una colonna `Margine %` calcolata da `Prezzo` e `Costo` e poi crei un **grafico** del margine per **categoria**.', 'Write a request for Copilot in Excel that adds a `Margine %` column computed from `Prezzo` and `Costo` and then creates a **chart** of margin by **category**.'), '', [re('Margine\s*%', L('La nuova colonna', 'The new column')), re('Prezzo[\s\S]*Costo|Costo[\s\S]*Prezzo', L('Da prezzo e costo', 'From price and cost')), re('grafico|chart', L('Un grafico', 'A chart')), re('categori', L('Per categoria', 'By category'))], '', 'Aggiungi una colonna Margine % calcolata come (Prezzo - Costo) / Prezzo, poi crea un grafico a barre del margine medio per categoria.'), [
            dMatch(pMatch(), [[L('Formula', 'Formula'), L('Nuova colonna calcolata', 'New computed column')], [L('Tabella pivot', 'Pivot table'), L('Riassume per gruppi', 'Summarises by groups')], [L('Evidenziare', 'Highlighting'), L('Formattazione condizionale', 'Conditional formatting')], ['PowerPoint', L('Slide da un documento', 'Slides from a document')]], L('Numeri e slide.', 'Numbers and slides.')),
            dFlash(pFlash(), [[L('Copilot in Excel lavora meglio con una tabella formattata', 'Copilot in Excel works better with a formatted table'), true], [L('Le formule generate non vanno mai controllate', 'Generated formulas never need checking'), false], [L('Copilot può creare grafici', 'Copilot can create charts'), true], [L('PowerPoint Copilot non legge documenti Word', 'PowerPoint Copilot cannot read Word documents'), false]], L('Analisi assistita.', 'Assisted analysis.')),
        ]),
        lesson('teams', L('Teams e protezione dei dati', 'Teams and data protection'), [
            P('In **Teams** Copilot riassume le riunioni, elenca decisioni e attività, e risponde a domande come “che cosa ha detto Anna sul budget?”, anche se sei arrivato in ritardo. Durante la riunione può funzionare anche senza salvare la trascrizione, ma in quel caso le sue risposte non restano disponibili dopo: per avere il riepilogo a riunione finita serve che la **trascrizione** sia attiva (le regole le decide l’amministratore). Nelle chat riassume le conversazioni lunghe.', 'In **Teams** Copilot summarises meetings, lists decisions and tasks, and answers questions like “what did Anna say about the budget?”, even if you joined late. During the meeting it can also work without saving the transcript, but then its answers are not available afterwards: to get the recap once the meeting is over, **transcription** must be on (the administrator sets the rules). In chats it summarises long conversations.'),
            P('Per i clienti aziendali Microsoft dichiara una **protezione dei dati aziendali**: richieste e risposte restano entro i confini del servizio e non vengono usate per addestrare i modelli di base. Copilot rispetta permessi ed etichette di riservatezza: se un file è condiviso con troppe persone, Copilot lo può trovare. Per questo la pulizia dei permessi è importante prima di attivarlo.', 'For business customers Microsoft states **enterprise data protection**: prompts and responses stay within the service boundary and are not used to train the foundation models. Copilot respects permissions and sensitivity labels: if a file is shared with too many people, Copilot can find it. That is why cleaning up permissions matters before turning it on.'),
            Fig(L(fig_mscopilot_perms('it'), fig_mscopilot_perms('en')),
                L('La tua domanda arriva a Copilot, che cerca solo ciò che puoi aprire. Il tuo report e il budget del team sono trovati; il file degli stipendi riservato a HR è escluso; una copia degli stipendi condivisa con tutti viene trovata, evidenziata in rosa.', 'Your question reaches Copilot, which searches only what you can open. Your report and the team budget are found; the salaries file restricted to HR is left out; a copy of the salaries shared with everyone is found, highlighted in pink.'),
                L('Copilot rispetta i permessi, quindi un file condiviso troppo diventa visibile a tutti.', 'Copilot respects permissions, so an overshared file becomes visible to everyone.')),
        ], [
            Q('t1', L('Che cosa serve per avere il riepilogo di Copilot anche dopo la riunione Teams?', 'What is needed to have Copilot’s recap after the Teams meeting too?'), [L('La trascrizione della riunione attiva', 'Meeting transcription turned on'), L('Niente', 'Nothing'), L('Un video su YouTube', 'A YouTube video'), L('Un file Excel', 'An Excel file')], 0, L('Senza trascrizione, Copilot aiuta solo durante la riunione.', 'Without transcription, Copilot helps only during the meeting.')),
            Q('t2', L('Perché sistemare i permessi dei file prima di attivare Copilot?', 'Why fix file permissions before enabling Copilot?'), [L('Copilot trova ciò a cui l’utente ha accesso, anche per errore', 'Copilot finds what the user can access, even by mistake'), L('Per velocizzarlo', 'To speed it up'), L('Non serve', 'It is not needed'), L('Per cambiare lingua', 'To change language')], 0, L('File condivisi troppo diventano visibili.', 'Over-shared files become findable.')),
            Q('t3', L('Che cosa dichiara la protezione dei dati aziendali?', 'What does enterprise data protection state?'), [L('I dati non addestrano i modelli di base', 'Data does not train the foundation models'), L('I dati sono pubblici', 'Data is public'), L('Nessuna regola', 'No rules'), L('I dati vanno a terzi', 'Data goes to third parties')], 0, L('Per i clienti aziendali.', 'For business customers.')),
        ], task('text', L('Scrivi tre domande da fare a Copilot dopo una riunione Teams, una per riga con `-`, tra cui una sulle **decisioni** e una sulle **attività** assegnate.', 'Write three questions to ask Copilot after a Teams meeting, one per line with `-`, including one about **decisions** and one about assigned **tasks**.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre domande', 'Three questions')), re('decision', L('Sulle decisioni', 'About decisions')), re('attivit|compit|task|azion|action', L('Sulle attività', 'About tasks'))], '', "- Quali decisioni sono state prese?\n- Quali attività sono state assegnate e a chi?\n- Ci sono punti rimasti in sospeso?"), [
            dMatch(pMatch(), [[L('Riepilogo riunione', 'Meeting recap'), L('Decisioni e attività', 'Decisions and tasks')], [L('Trascrizione', 'Transcription'), L('Testo della riunione', 'Meeting text')], [L('Etichette di riservatezza', 'Sensitivity labels'), L('Proteggono i documenti', 'Protect documents')], [L('Permessi', 'Permissions'), L('Cosa Copilot può trovare', 'What Copilot can find')]], L('Riunioni e dati.', 'Meetings and data.')),
            dFlash(pFlash(), [[L('Copilot rispetta i permessi esistenti', 'Copilot respects existing permissions'), true], [L('Senza trascrizione, il riepilogo di Copilot resta disponibile dopo la riunione', 'Without transcription, Copilot’s recap stays available after the meeting'), false], [L('Un file condiviso con tutti può comparire nelle risposte', 'A file shared with everyone can show up in answers'), true], [L('I permessi non contano con Copilot', 'Permissions do not matter with Copilot'), false]], L('Ordine nei permessi, sicurezza nelle risposte.', 'Tidy permissions, safe answers.')),
        ]),
        lesson('prompts', L('Scrivere prompt al lavoro', 'Writing prompts at work'), [
            P('Microsoft suggerisce di costruire le richieste con quattro elementi: **obiettivo** (cosa vuoi), **contesto** (perché e per chi), **fonti** (quali file, email o riunioni usare) e **aspettative** (formato e tono). Con le fonti giuste Copilot lavora sui tuoi documenti invece di inventare.', 'Microsoft suggests building requests from four elements: **goal** (what you want), **context** (why and for whom), **sources** (which files, emails or meetings to use) and **expectations** (format and tone). With the right sources Copilot works on your documents instead of inventing.'),
            C('Obiettivo: prepara un riepilogo del progetto Alfa.
Contesto: per il direttore, che non ha seguito le riunioni.
Fonti: /Verbale_marzo.docx e le email con oggetto “Alfa”.
Aspettative: una pagina, tono formale, rischi in evidenza.', 'text'),
            P('Rileggi sempre: Copilot vede solo ciò a cui **tu** hai accesso, ma può riassumere male o perdere un dettaglio. Per le decisioni importanti torna al documento originale.', 'Always reread: Copilot only sees what **you** have access to, but it can summarise badly or miss a detail. For important decisions go back to the original document.'),
            Tip('La prima risposta è una bozza: continua nella stessa chat con richieste brevi («accorcia», «aggiungi le scadenze», «togli il gergo tecnico»). Per indicare un documento preciso digita `/` e sceglilo dall’elenco: è il modo più sicuro per dire a Copilot da dove prendere le informazioni.', 'The first answer is a draft: carry on in the same chat with short requests (“shorten it”, “add the deadlines”, “drop the jargon”). To point to a specific document, type `/` and pick it from the list: it is the surest way to tell Copilot where to take the information from.'),
        ], [
            Q('mp1', L('Quali sono i quattro elementi del prompt?', 'What are the four prompt elements?'), [L('Obiettivo, contesto, fonti, aspettative', 'Goal, context, sources, expectations'), L('Saluto, testo, firma, data', 'Greeting, text, signature, date'), L('Titolo, corpo, allegato, invio', 'Title, body, attachment, send'), L('Domanda e basta', 'Just the question')], 0, L('Più indicazioni, risultati migliori.', 'More guidance, better results.')),
            Q('mp2', L('Perché indicare le fonti?', 'Why name the sources?'), [L('Così lavora sui tuoi documenti', 'So it works on your documents'), L('Per pagare meno', 'To pay less'), L('Per cambiare lingua', 'To change language'), L('Non serve', 'It is not needed')], 0, L('Meno invenzioni.', 'Less invention.')),
            Q('mp3', L('Che cosa vede Copilot di Microsoft 365?', 'What does Microsoft 365 Copilot see?'), [L('Solo i dati a cui hai accesso tu', 'Only data you have access to'), L('Tutti i file dell’azienda', 'All company files'), L('Internet soltanto', 'The internet only'), L('Niente', 'Nothing')], 0, L('Rispetta i permessi.', 'It respects permissions.')),
        ], task('text', L('Scrivi un prompt in quattro righe che iniziano con `Obiettivo:`, `Contesto:`, `Fonti:` e `Aspettative:`.', 'Write a prompt in four lines starting with `Obiettivo:`, `Contesto:`, `Fonti:` and `Aspettative:`.'), '', [re('^Obiettivo\s*:\s*\S', L('C’è l’obiettivo', 'The goal is there')), re('^Contesto\s*:\s*\S', L('C’è il contesto', 'The context is there')), re('^Fonti\s*:\s*\S', L('Ci sono le fonti', 'The sources are there')), re('^Aspettative\s*:\s*\S', L('Ci sono le aspettative', 'The expectations are there'))], '', "Obiettivo: scrivi la bozza della newsletter di maggio.\nContesto: per i clienti, che conoscono già il prodotto.\nFonti: /Novità_maggio.docx.\nAspettative: 200 parole, tono amichevole, un invito finale."), [
            dOrder(pSort(), [L('Obiettivo', 'Goal'), L('Contesto', 'Context'), L('Fonti', 'Sources'), L('Aspettative', 'Expectations')], L('Un prompt completo.', 'A complete prompt.')),
            dFlash(pFlash(), [[L('Indicare un file come fonte riduce le invenzioni', 'Naming a file as a source reduces invention'), true], [L('Copilot legge anche i file che tu non puoi aprire', 'Copilot reads files you cannot open'), false], [L('Un riassunto va riletto prima di decidere', 'A summary should be reread before deciding'), true], [L('Il tono non si può chiedere', 'Tone cannot be requested'), false]], L('Prompt da ufficio.', 'Office prompts.')),
        ]),
        lesson('agents', L('Copilot Chat, agenti e Pagine', 'Copilot Chat, agents and Pages'), [
            P('**Microsoft 365 Copilot Chat** è la chat di Copilot per gli account di lavoro e scuola, con la stessa protezione dei dati aziendali. Senza la licenza completa risponde soprattutto con informazioni dal web e dai file che carichi; con la licenza **Microsoft 365 Copilot** può usare anche email, documenti e riunioni a cui hai accesso. Che cosa è incluso lo decide il piano della tua organizzazione.', '**Microsoft 365 Copilot Chat** is Copilot’s chat for work and school accounts, with the same enterprise data protection. Without the full licence it answers mainly with information from the web and the files you upload; with the **Microsoft 365 Copilot** licence it can also use the emails, documents and meetings you have access to. What is included depends on your organisation’s plan.'),
            Fig(L(fig_mscopilot_licence('it'), fig_mscopilot_licence('en')),
                L('Due riquadri. A sinistra Copilot Chat senza licenza completa usa il web e i file che carichi. A destra, con la licenza Microsoft 365 Copilot, agli stessi due si aggiungono email, documenti, riunioni e chat, solo quelli a cui hai accesso. Sotto una fascia verde: stessa protezione dei dati aziendali.', 'Two boxes. On the left, Copilot Chat without the full licence uses the web and the files you upload. On the right, with the Microsoft 365 Copilot licence, emails, documents, meetings and chats are added to those two, only the ones you have access to. Below, a green band: same enterprise data protection.'),
                L('La licenza non cambia la chat, cambia ciò che può leggere.', 'The licence does not change the chat, it changes what it can read.')),
            P('Gli **agenti** sono assistenti specializzati: **Researcher** fa ricerche in più passaggi tra web e dati di lavoro e scrive un rapporto con le fonti; **Analyst** ragiona sui dati (per esempio un foglio Excel) e mostra i calcoli che ha fatto. Le aziende possono creare agenti propri, con istruzioni e fonti scelte. Le **Pagine** di Copilot trasformano una risposta in un documento modificabile da condividere e completare con i colleghi.', '**Agents** are specialised assistants: **Researcher** runs multi-step research across the web and work data and writes a report with sources; **Analyst** reasons over data (an Excel sheet, for example) and shows the calculations it made. Companies can build their own agents, with chosen instructions and sources. Copilot **Pages** turn an answer into an editable document to share and complete with colleagues.'),
            Tip('Prima di inoltrare un rapporto di un agente, apri le fonti principali: un rapporto ben scritto può contenere un dato sbagliato.', 'Before forwarding an agent’s report, open the main sources: a well-written report can still contain a wrong figure.'),
        ], [
            Q('ag1', L('Quale agente è pensato per ragionare sui dati di un foglio Excel?', 'Which agent is designed to reason over the data in an Excel sheet?'), ['Researcher', 'Analyst', 'Outlook', 'Pages'], 1, L('Mostra anche i calcoli.', 'It also shows the calculations.')),
            Q('ag2', L('A che cosa servono le Pagine di Copilot?', 'What are Copilot Pages for?'), [L('A stampare le chat', 'Printing chats'), L('A salvare le password', 'Saving passwords'), L('A trasformare una risposta in un documento condiviso', 'Turning an answer into a shared document'), L('A creare siti web pubblici', 'Creating public websites')], 2, L('Si completano con i colleghi.', 'They are completed with colleagues.')),
            Q('ag3', L('Che cosa decide a quali dati di lavoro accede Copilot Chat?', 'What decides which work data Copilot Chat can access?'), [L('Il browser che usi', 'The browser you use'), L('La lunghezza del prompt', 'The prompt length'), L('L’ora del giorno', 'The time of day'), L('La licenza e le regole della tua organizzazione', 'Your organisation’s licence and rules')], 3, L('Senza licenza completa, soprattutto web e file caricati.', 'Without the full licence, mainly web and uploaded files.')),
        ], task('text', L('Scrivi una richiesta per l’agente **Researcher** che chieda un **rapporto** su un tema di lavoro, indicando le **fonti** da usare (web, email o documenti) e il **formato**.', 'Write a request for the **Researcher** agent asking for a **report** on a work topic, stating the **sources** to use (web, emails or documents) and the **format**.'), '', [re('rapporto|report|ricerca|research', L('Chiedi un rapporto', 'You ask for a report')), re('fonti|sources?|web|email|mail|document|file', L('Indichi le fonti', 'You state the sources')), re('formato|format|pagin|page|punti|points|tabella|table|sezion|section', L('Indichi il formato', 'You state the format'))], '', 'Prepara un rapporto sui fornitori di imballaggi riciclabili in Italia: usa il web e le email del team acquisti degli ultimi tre mesi. Formato: due pagine con una tabella di confronto e le fonti.'), [
            dMatch(pMatch(), [['Copilot Chat', L('Chat per account di lavoro', 'Chat for work accounts')], ['Researcher', L('Rapporto con fonti', 'Report with sources')], ['Analyst', L('Ragiona sui dati', 'Reasons over data')], [L('Pagine', 'Pages'), L('Documento condiviso', 'Shared document')]], L('Gli strumenti di Copilot.', 'Copilot’s tools.')),
            dFlash(pFlash(), [[L('Le aziende possono creare agenti propri', 'Companies can build their own agents'), true], [L('Copilot Chat legge sempre tutte le email aziendali', 'Copilot Chat always reads every company email'), false], [L('Le fonti di un rapporto vanno controllate', 'A report’s sources should be checked'), true], [L('Un rapporto ben scritto è sempre corretto', 'A well-written report is always correct'), false]], L('Agenti al lavoro.', 'Agents at work.')),
        ]),
    ],
];
